class Base {
private:
    int pvt = 1;
protected:
    int prot = 2;
public:
    int pub = 3;
    int getPVT() { return pvt; }
};

class PrivateDerived : private Base {
public:
    // Can access protected (now private here)
    int getProt() { return prot; }

    // Can access public (now private here)
    int getPub() { return pub; }

    // Can call public methods (now private here)
    int getBasePVT() { return getPVT(); }
};

int main() {
    PrivateDerived obj;

    // obj.pub;        // ERROR: pub is now private
    // obj.getPVT();   // ERROR: getPVT is now private
    // obj.prot;       // ERROR: prot is now private

    obj.getPub();      // OK: wrapped in public method
    obj.getProt();     // OK: wrapped in public method

    // Base* ptr = &obj;  // ERROR: private inheritance
}
